STRS = ["", "a", "'", '"', "'\"", "\\", "\n", "\t", "\r", "\x00", "\x7f",
        "\x1b", "\x85", "é", "日本", "a'b\"c", "\\n", " ", "\v", "\f",
        " \u00a0", "é", "\U0001F600", "\udc3f", "\ue000"]

for i, s in enumerate(STRS):
    if any('\u2028' <= ch <= '\uffff' for ch in s) or any(ch == '\u0085' for ch in s):
        def _manrepr(s=s):
            # manual repr for strings containing non-ascii chars
            out = '"'
            for ch in s:
                cp = ord(ch)
                if ch == '\\':
                    out += '\\\\'
                elif ch == '"':
                    out += '\\"'
                elif cp < 32 or cp == 127:
                    name = {9:'\\t',10:'\\n',13:'\\r',8:'\\b',11:'\\v',12:'\\f'}.get(cp)
                    if name is not None:
                        out += name
                    else:
                        out += '\\x%02x' % cp
                elif cp > 127:
                    if cp >= 0x10000:
                        out += '\\U%08x' % cp
                    else:
                        out += '\\u%04x' % cp
                else:
                    out += ch
            out += '"'
            return out
        r("s%d" % i, lambda s=s: _manrepr(s))
    else:
        r("s%d" % i, lambda s=s: repr(s))
    r("p%d" % i, lambda s=s: repr(str(s)))

